const listPluginsForEvent = `-- name: ListPluginsForEvent :many
SELECT p.id, p.plugin_key
FROM plugins p JOIN plugin_company_settings s ON s.plugin_id = p.id
WHERE s.company_id = $1 AND s.enabled AND p.status IN ('ready','upgrade_pending')
  AND $2::text = ANY(p.events) AND 'events.subscribe' = ANY(p.granted_capabilities)
ORDER BY p.plugin_key
`

type ListPluginsForEventParams struct {
	CompanyID uuid.UUID
	Verb      string
}

type ListPluginsForEventRow struct {
	ID        uuid.UUID
	PluginKey string
}

// Plugins ativos, ligados na empresa e assinantes do verbo, com a capacidade events.subscribe concedida.
func (q *Queries) ListPluginsForEvent(ctx context.Context, arg ListPluginsForEventParams) ([]ListPluginsForEventRow, error) {
	rows, err := q.db.Query(ctx, listPluginsForEvent, arg.CompanyID, arg.Verb)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPluginsForEventRow{}
	for rows.Next() {
		var i ListPluginsForEventRow
		if err := rows.Scan(&i.ID, &i.PluginKey); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

